"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["95975"],{98382(e){e.exports=JSON.parse('{"id":"FIN-123","slug":"matching-principle","term":"Matching Principle","also_known_as":[],"difficulty":"Beginner","definition":"The matching principle is the accounting rule that expenses should be recorded in the same period as the revenue they helped to generate.","explanation":["The aim is to show the true profit of each period. If a business recorded revenue in one month and the related costs in another, both months would give a misleading picture.","Suppose a shop buys stock for 6,000 in March and sells it for 10,000 in April. Under the matching principle, the 6,000 cost is recorded as an expense in April, alongside the 10,000 of revenue, giving a profit of 4,000 in April. In March, the stock sits on the balance sheet as inventory.","The principle also explains depreciation. A machine costing 50,000 that will be used for five years helps produce revenue in each of those years, so its cost is spread at 10,000 a year rather than recorded all at once.","Some costs cannot be linked to specific sales, such as office rent or administrative salaries. These are recorded in the period they relate to. The matching principle is a core part of accrual accounting and helps make profit figures meaningful."],"note":"","total":1500,"prev":{"slug":"marketplace-model","term":"Marketplace Model"},"next":{"slug":"material-adverse-change","term":"Material Adverse Change"}}')}}]);